style.css:
@-moz-document domain("techpowerup.com"), domain("www.techpowerup.com") {
/* Server-rendered LIGHT site with no custom-property theme layer: every
     surface and ink is hardcoded, and classes are stable and unhashed, so we
     retheme through them, soften all light borders globally and keep TPU blue as
     the accent. /forums/ is XenForo on the same host. */

  :root {
    color-scheme: dark;
  }

  /* ---- Base ---- */
  html,
  body {
    background-color: #14181d !important;
    color: #c4cdd6 !important;
  }

  /* Soften every light border */
  *,
  *::before,
  *::after {
    border-color: #262c33 !important;
  }

  /* ---- Main content surfaces ---- */
  .page,
  .contnt,
  .contentArea,
  .contentbox,
  .content,
  #content,
  .main,
  .container,
  .wrap,
  .wrapper {
    background-color: transparent !important;
    color: #c4cdd6 !important;
  }

  .page {
    background-color: #14181d !important;
  }

  /* Elevated panels / boxes */
  .contentbox,
  .infobox,
  .sidebar-box,
  .box,
  .panel,
  aside .widget,
  .frontpage-extra,
  .todayslist,
  .todaysfiles,
  .todaysreviews {
    background-color: #1c2128 !important;
    border-color: #262c33 !important;
  }

  /* ---- Page header (logo bar) ---- */
  .page-header,
  .v-port > span > div,
  header {
    background-color: #0d1117 !important;
    color: #e6edf3 !important;
  }

  .page-header {
    border-bottom: 1px solid #262c33 !important;
  }

  /* Black wordmark. hue-rotate is a linear-matrix approximation that desaturates,
     so brand #c20000 lands salmon; saturate(4) brightness(.92) restores it, and
     the achromatic wordmark is unaffected. */
  .page-header__logo {
    filter: invert(1) hue-rotate(180deg) saturate(4) brightness(0.92) !important;
  }

  /* Both toggles are SVG bg-images with black ink */
  .navigation-toggle,
  .s--toggle {
    filter: invert(1) !important;
  }

  /* ---- Main nav (keep the dark-blue brand identity) ---- */
  nav#menu,
  #menu,
  .p-nav,
  .p-nav-inner {
    background-color: #161d27 !important;
    border-color: #21262d !important;
  }

  nav#menu a,
  #menu a,
  #menu li > span,
  .p-navEl-link {
    color: #d6e2ee !important;
  }

  nav#menu li:hover,
  #menu li:hover,
  nav#menu a:hover,
  .p-navEl-link:hover {
    background-color: #21303f !important;
    color: #ffffff !important;
  }

  /* Dropdown submenus in the nav must stay opaque */
  #menu ul ul,
  #menu li ul,
  .p-nav .menu,
  .menu,
  .menu-content,
  .tooltip,
  .tooltip-content,
  .autoComplete,
  .autoCompleteList {
    background-color: #1c2128 !important;
    border-color: #2d333b !important;
    box-shadow: 0 8px 24px rgba(0, 0, 0, 0.5) !important;
  }

  #menu ul ul a,
  .menu-content a,
  .menu-content,
  .autoCompleteList a {
    color: #c4cdd6 !important;
  }

  /* An opened nav dropdown auto-focuses its first row, so :focus and .is-selected
     need covering as well as :hover. */
  #menu ul ul a:hover,
  #menu ul ul a:focus,
  .menu-linkRow:hover,
  .menu-linkRow:focus,
  .menu-linkRow.is-selected,
  .autoCompleteList a:hover,
  .autoCompleteList a:focus {
    background-color: #21303f !important;
    color: #ffffff !important;
  }

  /* Spec-DB "Add Filters" flyout panel */
  .dropdown-content,
  .dropdown-content ul,
  .dropdown-content li,
  .js-filter-dropdown .dropdown-content {
    background-color: #1c2128 !important;
    border-color: #2d333b !important;
    color: #c4cdd6 !important;
  }

  .dropdown-content {
    box-shadow: 0 8px 24px rgba(0, 0, 0, 0.5) !important;
  }

  .dropdown-content a {
    color: #5fb0e6 !important;
  }

  .dropdown-content li:hover,
  .dropdown-content a:hover {
    background-color: #21303f !important;
    color: #ffffff !important;
  }

  /* The separator is a solid block, not a border */
  .dropdown > .dropdown-content > .divider {
    background-color: #2d333b !important;
  }

  /* Selected-filter editor rows in the spec-DB filter bar */
  .filter-item,
  .js-filter-item,
  .filter-options {
    background-color: #1c2128 !important;
    border-color: #262c33 !important;
    color: #c4cdd6 !important;
  }

  .filter-title,
  .filter-item a,
  .filter-options a {
    color: #5fb0e6 !important;
  }

  .filter-list-item,
  .filter-title-remove-hint {
    color: #8b949e !important;
  }

  /* The site's own modal, appended to <body> at click time. Must stay OPAQUE:
     the page scrolls under it. */
  .popup_container .popup_inner {
    background-color: #161d27 !important;
    background-image: none !important;
    border: 1px solid #2d333b !important;
    box-shadow: 0 12px 32px rgba(0, 0, 0, 0.6) !important;
  }

  .popup_content h2 {
    background-color: #21262d !important;
    border-color: #2d333b !important;
    color: #e6edf3 !important;
  }

  .popup_content #popup_content {
    background-color: #1c2128 !important;
    border-color: #2d333b !important;
    color: #c4cdd6 !important;
  }

  /* ---- Search / sidebar strip (.s-) ---- */
  .s-,
  .s---responsive,
  div[class^="s-"][class*="responsive"] {
    background-color: #0d1117 !important;
    border-color: #21262d !important;
  }

  .s--item,
  .s--search,
  .s--login,
  .s--drivers,
  .s--newposts,
  .s--top-rev-s,
  .s--youtube,
  .s--top-news {
    background-color: transparent !important;
    color: #c4cdd6 !important;
  }

  .s--item__heading,
  .s--item h1 {
    color: #e6edf3 !important;
  }

  .s--toggle-button {
    color: #c4cdd6 !important;
  }

  /* Sidebar entries + hardcoded dark timestamps */
  .s--newposts__list a,
  .s--top-rev-s__list a,
  .s--top-news__list a {
    color: #5fb0e6 !important;
  }

  .s--newposts__time,
  .s--top-rev-s__date,
  .s--top-news__date,
  .s--newposts li time,
  .s--top-rev-s li time {
    color: #8b949e !important;
  }

  /* Re-assert at (0,2,1) over the blanket `a:link` (0,1,1), which would flatten
     all three vendor hues to one blue. */
  .s--drivers a.s--drivers__driver--nvidia {
    color: #7ec242 !important;
  }

  .s--drivers a.s--drivers__driver--amd {
    color: #e8585c !important;
  }

  .s--drivers a.s--drivers__driver--intel {
    color: #5fb0e6 !important;
  }

  /* ---- News feed ---- */
  article.newspost,
  .newspost,
  .review-carousel,
  .patreon-previews,
  .featured-news {
    background-color: transparent !important;
    color: #c4cdd6 !important;
  }

  article.newspost {
    border-bottom: 1px solid #21262d !important;
  }

  /* Rows carry an alternating light card bg */
  .reviewlist-bit,
  .reviewlist-bit.clearfix,
  div.reviewlist-bit {
    background-color: #1c2128 !important;
    border-color: #262c33 !important;
    color: #c4cdd6 !important;
  }

  .reviewlist-bit .title a {
    color: #cfe2f3 !important;
  }

  .reviewlist-bit .teaser,
  .reviewlist-bit .meta,
  .reviewlist-bit .date,
  .reviewlist-bit .author,
  .reviewlist-bit .category,
  .reviewlist-bit .meta span,
  .reviewlist-bit .meta b {
    color: #8b949e !important;
  }

  .reviewlist-bit .meta a,
  .reviewlist-bit .category a,
  .reviewlist-bit .author a {
    color: #5fb0e6 !important;
  }

  /* Review-list filter bar */
  .reviewlist-search,
  .reviewlist-search > div,
  #filtertable,
  #filtertable > div {
    background-color: #1c2128 !important;
    border-color: #262c33 !important;
    color: #c4cdd6 !important;
  }

  .reviewlist-search label,
  #filtertable label {
    color: #c4cdd6 !important;
  }

  /* Pager / pagination pills */
  .pager a,
  .pager span,
  .prevnext a,
  .pagination a,
  .pagination span,
  nav.pager a {
    background-color: #21262d !important;
    color: #d6e2ee !important;
    border-color: #2d333b !important;
  }

  .pager a:hover,
  .prevnext a:hover,
  .pagination a:hover {
    background-color: #2d333b !important;
    color: #ffffff !important;
  }

  /* `.pager a:hover` above is (0,2,1), above a bare `.pager .current` (0,2,0),
     so the current page must claim its own hover. */
  .pager .current,
  .pager .current:hover,
  .pager a.active,
  .pagination .current,
  .pagination .current:hover {
    background-color: #2563a8 !important;
    color: #ffffff !important;
  }

  .pager a.disabled,
  .prevnext a.disabled {
    color: #7d8590 !important;
  }

  /* Plain LABELS, not links; `.pager span` would pill them like page links */
  .pager > span.counts,
  .pager > span.description,
  .pager > span.buttons {
    background-color: transparent !important;
    border-color: transparent !important;
    color: #8b949e !important;
  }

  /* Chip labels are ::before/::after text; its bubble SVG is near-white filled
     and survives on a dark plate. */
  .discuss {
    background-color: #1c2128 !important;
    border-color: #2d333b !important;
    color: #5fb0e6 !important;
    opacity: 1 !important;
  }

  .discuss::before {
    color: #e6edf3 !important;
  }

  .discuss::after {
    color: #8b949e !important;
  }

  .discuss:hover {
    background-color: #21303f !important;
    border-color: #3d4450 !important;
  }

  /* Closing strip of a review article page */
  .review .contnt > footer {
    background-color: #1c2128 !important;
  }

  /* The Patreon fade-out is a background-IMAGE over a transparent box, so
     background-color never reaches it: restate the stop in page tone. */
  .review .contnt .review-patreon-required::before {
    background: linear-gradient(to bottom, rgba(20, 24, 29, 0) 25%, #14181d 100%) !important;
  }

  /* Review one-page nav + image-comparison controls */
  .onepage-nav,
  .image-comparison2__toggle-fullscreen,
  .image-comparison2__zoom {
    background-color: #1c2128 !important;
    color: #e6edf3 !important;
    border-color: #262c33 !important;
  }

  .image-comparison2__zoom:hover {
    background-color: #21303f !important;
  }

  /* Article body image placeholders */
  .responsive-image-xx,
  [class*="responsive-image"] {
    background-color: transparent !important;
  }

  /* Site paints <time> a hardcoded #404040 */
  time,
  .post-date,
  .newspost time,
  .contnt time {
    color: #8b949e !important;
  }

  /* Carousel + featured-news tiles carry a light bg */
  .review-carousel__items,
  .review-carousel-item,
  .review-carousel-item__title,
  .featured-news__item,
  .featured-news__image,
  .featured-news__title,
  .patreon-previews__item {
    background-color: #1c2128 !important;
    color: #c4cdd6 !important;
  }

  .review-carousel-item__title,
  .featured-news__title,
  .featured-news__item-title {
    color: #cfe2f3 !important;
  }

  /* Separators are a 3px full-height ::before */
  .review-carousel-item::before,
  .review-carousel-item::after {
    background-color: #262c33 !important;
  }

  .featured-news__image {
    background-color: #161d27 !important;
  }

  /* Eleven `.flags .flag.*` variants plus plain category tags TPU colours with an
     INLINE background-color. The neutral fallback matches `.flags .flag` (0,2,0)
     WITHOUT !important: it beats the site's `gray` by source order while the
     inline colour still shows through, and each `.flag.*` below wins via its
     own !important. */
  .flag,
  .flag span,
  span.flag {
    color: #ffffff !important;
  }

  .flags .flag {
    background-color: #3d4450;
  }

  .flag.draft {
    background-color: #6b4a12 !important;
  }

  .flag.pr {
    background-color: #21303f !important;
  }

  .flag.featured {
    background-color: #7d2a2c !important;
  }

  .flag.editorial {
    background-color: #2a5c2d !important;
  }

  .flag.updated {
    background-color: #2a6363 !important;
  }

  .flag.review {
    background-color: #6b3823 !important;
  }

  .flag.article {
    background-color: #6b6224 !important;
  }

  .flag.sponsored {
    background-color: #6e5d27 !important;
  }

  .flag.live {
    background-color: #a51414 !important;
  }

  .flag.ces,
  .flag.computex {
    background-color: #6e2c74 !important;
  }

  .flag.video {
    background-color: #8c1312 !important;
  }

  /* Reclaim at (0,2,0): the broad `.latest` downloads rule below would erase
     this signal. */
  .flag.latest {
    background-color: #2a5c2d !important;
  }

  /* Front-page poll widget */
  .frontpagepoll,
  .frontpagepoll .poll,
  aside.frontpagepoll {
    background-color: #1c2128 !important;
    color: #c4cdd6 !important;
    border-color: #262c33 !important;
  }

  .frontpagepoll label,
  .frontpagepoll li,
  .frontpagepoll .pollanswer {
    color: #c4cdd6 !important;
    background-color: transparent !important;
  }

  /* Retone the track only, the fill is the data */
  .frontpagepoll ul.results .bar,
  .newspoll > ul.results > li .bar {
    background-color: #21262d !important;
  }

  .newspoll_btn::before {
    color: #8b949e !important;
  }

  /* A raster PNG no background-color rule reaches; invert like the logo,
     hue-rotate/saturate keeping the "?" bubble orange. */
  .newspoll_btn {
    filter: invert(1) hue-rotate(180deg) saturate(1.6) brightness(0.95) !important;
  }

  /* Separators are a `content:"-"` ::after */
  .todayslist ul > li::after {
    color: #8b949e !important;
  }

  /* Pinned / featured news tiles + their image wells */
  .pinned-news__item,
  .pinned-news2__item,
  .pinned-news2__image {
    background-color: #1c2128 !important;
  }

  /* Hover also draws an `outline`, out of reach of a bg repaint */
  .featured-news__item > a:hover,
  .pinned-news__item > a:hover,
  .pinned-news2__item > a:hover {
    background-color: #21303f !important;
    outline-color: #2f74c0 !important;
  }

  .pinned-news__title,
  .pinned-news2__item-title {
    color: #cfe2f3 !important;
  }

  /* "Up next" strip and the notice bar (tint + PNG stripe) */
  .upnext {
    background-color: #3a2020 !important;
    border-color: #5c3030 !important;
  }

  .infobar {
    background-color: #3a2f10 !important;
    background-image: none !important;
    border-bottom-color: #6e5d27 !important;
  }

  /* The notice text IS an <a>, so scope under `.infobar` for (0,2,1) over the
     blanket `a:link` (0,1,1). */
  .infobar,
  .infobar a.infobar__link {
    color: #e3c46a !important;
  }

  .infobar a.infobar__link:hover {
    color: #ffe08a !important;
  }

  /* Tag-cloud pills on news articles */
  .tagcloud a {
    background-color: #21262d !important;
    color: #c4cdd6 !important;
  }

  .tagcloud a:hover {
    background-color: #2d333b !important;
    color: #ffffff !important;
  }

  /* Vendor-logo PNG ink runs from pure black to full colour, so a dark plate
     erases the black ones and no filter keeps the coloured ones honest — the
     plate must stay LIGHT, only muted. */
  .newsicon {
    background-color: #c9d1d9 !important;
  }

  /* Fallback plate whose per-category colour TPU sets INLINE: as with `.flags
     .flag`, no !important at (0,1,0) so we win by source order and the inline
     colour still shows through. White ink is the site's. */
  .patreon-previews__tag {
    background-color: #3d4450;
  }

  /* `scrollbar-color` at the end of this sheet is Firefox-only */
  .patreon-previews__list-wrapper::-webkit-scrollbar {
    background-color: #14181d !important;
  }

  .patreon-previews__list-wrapper::-webkit-scrollbar-thumb {
    background-color: #2d333b !important;
  }

  .newspost h2,
  .newspost h1,
  .newspost-title {
    color: #e6edf3 !important;
  }

  /* Date separator */
  .datesep {
    background-color: #21303f !important;
    color: #d6e2ee !important;
    border-color: #2d333b !important;
  }

  /* TPU's native comment markup, not the XenForo .message posts */
  section.comments article.forumpost,
  article.forumpost.clearfix,
  .forumpost,
  .forumpost > footer,
  .forumpost .posttext,
  .posttext {
    background-color: #1c2128 !important;
    border-color: #262c33 !important;
    color: #c4cdd6 !important;
  }

  .forumpost header.userinfo {
    background-color: #161d27 !important;
    border-color: #21262d !important;
  }

  .forumpost .username,
  .forumpost .userinfo a {
    color: #cfe2f3 !important;
  }

  /* Hardcoded #666 user titles on the dark header */
  .forumpost .usertitle,
  .usertitle {
    color: #8b949e !important;
  }

  /* ---- Headings ---- */
  h1,
  h2,
  h3,
  h4,
  h5,
  h6 {
    color: #e6edf3 !important;
  }

  .contnt h1,
  .contnt h2,
  .text h2,
  .text h3 {
    color: #cfe2f3 !important;
  }

  /* ---- Body / article text ---- */
  .text,
  .text p,
  .text li,
  .text td,
  p,
  li,
  dd,
  dt,
  span,
  label {
    color: #c4cdd6 !important;
  }

  small,
  .small,
  .muted,
  .meta,
  .date,
  .byline,
  .newspost .meta {
    color: #8b949e !important;
  }

  /* Quotes (news posts, articles) */
  blockquote {
    background-color: #161d27 !important;
    color: #c4cdd6 !important;
    border-color: #2d333b !important;
  }

  /* On the news side the 4px left bar is the quote's only marker; XenForo's
     quote has no bar and keeps its amber attribution row instead. */
  .newspost blockquote,
  .posttext blockquote {
    border-left-color: #2f74c0 !important;
  }

  /* ---- Links ---- */
  a,
  a:link,
  a:visited {
    color: #5fb0e6 !important;
  }

  a:hover {
    color: #9bd4ff !important;
  }

  /* Broad `span` / `.contnt b` body rules match wrapped link text directly and
     win on the child, so hand the anchor's colour back down. Class-scoped
     children like `.flag span` still win on specificity. */
  a span,
  a b,
  a strong,
  a em,
  .contnt a b,
  .page a b,
  button span,
  .button span {
    color: inherit !important;
  }

  /* Search-hit marker built for the site's black ink. (0,1,1) outranks both the
     blanket `span` ink and the `a span` inherit-reclaim, so it keeps its own ink
     inside a link too. */
  span.highlight,
  .highlight {
    background-color: #6b5d10 !important;
    color: #ffe08a !important;
  }

  /* Nav / header / footer links handled by their own blocks */
  .page-header a,
  nav#menu a,
  #menu a {
    color: inherit !important;
  }

  /* ---- Tables (spec databases + review tables) ---- */
  table,
  table.items-desktop-table,
  .tablesorter,
  .drvtbl {
    background-color: transparent !important;
    color: #c4cdd6 !important;
    border-color: #2d333b !important;
  }

  th,
  thead th,
  table.items-desktop-table th,
  thead tr,
  .colheader,
  .colheader tr,
  tr.colheader {
    background-color: #1c2128 !important;
    color: #e6edf3 !important;
    border-color: #2d333b !important;
  }

  /* Some pages set a brand-navy header bg inline */
  th,
  th span,
  thead th span {
    color: #e6edf3 !important;
  }

  td {
    border-color: #21262d !important;
    color: #c4cdd6 !important;
  }

  /* Zebra striping + row hover */
  tr:nth-child(even) td,
  tr:nth-child(even),
  .even td,
  .alt td {
    background-color: #171c22 !important;
  }

  tr:nth-child(odd) td,
  .odd td {
    background-color: transparent !important;
  }

  tbody tr:hover td,
  table.items-desktop-table tbody tr:hover {
    background-color: #21303f !important;
  }

  /* Spec-table section / group rows TPU paints blue */
  .tablesorter caption,
  table caption,
  .group td,
  td.group {
    background-color: #21303f !important;
    color: #d6e2ee !important;
  }

  /* The site paints the zebra AND the 7px vendor stripe on the <tr>, leaving tds
     transparent. An opaque td would cover the stripe and flatten the zebra. */
  .items-desktop-table tbody tr,
  .contnt table tbody tr,
  table tbody tr[style],
  tr[class*="vendor-"] {
    background-color: transparent !important;
    color: #c4cdd6 !important;
  }

  .items-desktop-table tbody tr:nth-child(odd),
  .contnt table tbody tr:nth-child(odd) {
    background-color: #171c22 !important;
  }

  .items-desktop-table tbody tr td,
  .contnt table tbody tr td,
  tr[class*="vendor-"] td {
    background-color: transparent !important;
  }

  .items-desktop-table tbody tr:hover,
  .contnt table tbody tr:hover,
  tr[class*="vendor-"]:hover {
    background-color: #21303f !important;
  }

  .items-desktop-table tbody tr:hover td,
  .contnt table tbody tr:hover td,
  tr[class*="vendor-"]:hover td {
    background-color: transparent !important;
  }

  /* Spec-DB group / generation header rows */
  .generation-header,
  .generation-header-mobile {
    background-color: #21262d !important;
    color: #8b949e !important;
  }

  /* The band is a background-IMAGE (`linear-gradient(to right, transparent 7px,
     #e8e8e8 7px)`, the lead-in being the vendor stripe's gap), so
     background-color never clears it. Two classes, to outrank
     `table.items-desktop-table th` (0,1,2). */
  .items .generation-header,
  .items-desktop-table .generation-header,
