  .newspost > .live-blog-info {
    background-color: #16242e !important;
    color: #9bd4ff !important;
  }

  /* ---- Fancybox lightbox (news, live coverage, gallery) ----
     Prev/next/close are `<button>`s kept as TRANSPARENT hit-areas carrying only a
     background-image glyph, so the generic button rule both plates them over the
     photo and erases the glyphs. Size, position and opacity hover stay theirs. */

  .fancybox-container .fancybox-tpu-btn {
    background-color: transparent !important;
  }

  .fancybox-container .fancybox-tpu-btn-prev {
    background-image: url("data:image/svg+xml;charset=utf8,%3Csvg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 256 256'%3E%3Cpath d='M160 40 L72 128 L160 216' fill='none' stroke='%23e6edf3' stroke-width='26' stroke-linecap='round' stroke-linejoin='round'/%3E%3C/svg%3E") !important;
  }

  .fancybox-container .fancybox-tpu-btn-next {
    background-image: url("data:image/svg+xml;charset=utf8,%3Csvg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 256 256'%3E%3Cpath d='M96 40 L184 128 L96 216' fill='none' stroke='%23e6edf3' stroke-width='26' stroke-linecap='round' stroke-linejoin='round'/%3E%3C/svg%3E") !important;
  }

  .fancybox-container .fancybox-tpu-btn-close {
    background-image: url("data:image/svg+xml;charset=utf8,%3Csvg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 256 256'%3E%3Cpath d='M56 56 L200 200 M200 56 L56 200' fill='none' stroke='%23e6edf3' stroke-width='26' stroke-linecap='round'/%3E%3C/svg%3E") !important;
  }

  /* Shown when an ad blocker kills the image request */
  .fancybox-error {
    background-color: #1c2128 !important;
  }

  .fancybox-error p {
    color: #c4cdd6 !important;
  }

  /* ---- PhotoSwipe lightbox ( /gallery/ case pages ) ----
     Already dark; buttons are transparent hit-areas around an inline SVG with its
     own white fill, so only the generic button rule's plate is wrong. Hover is
     icon-opacity, never a plate, so it must be named or `button:hover` refills. */

  .pswp .pswp__button,
  .pswp .pswp__button:hover {
    background-color: transparent !important;
    border: 0 !important;
  }

  /* ---- Footer ----
     `<footer>` is a CONTENT tag here as much as chrome — comment timestamp rows,
     the review page-nav strip and the poll vote bar are bare ones — so match
     footer CLASSES, never the tag. */
  footer.site-footer,
  #footer,
  .page-footer,
  .footer,
  .p-footer {
    background-color: #0d1117 !important;
    color: #8b949e !important;
    border-top: 1px solid #21262d !important;
  }

  footer.site-footer a,
  #footer a,
  .p-footer a {
    color: #8b949e !important;
  }

  footer.site-footer a:hover,
  #footer a:hover,
  .p-footer a:hover {
    color: #c4cdd6 !important;
  }

  /* ---- XenForo forums ( /forums/ ) ---- */

  .p-body,
  .p-body-inner,
  .p-pageWrapper,
  .p-body-main,
  .p-body-content {
    background-color: transparent !important;
    color: #c4cdd6 !important;
  }

  .p-header,
  .p-header-inner {
    background-color: #0d1117 !important;
    color: #e6edf3 !important;
  }

  /* The forum logo is a scheme-dependent <picture>: dark-OS a white wordmark,
     light-OS a black one. Our header is ALWAYS dark, so branch on the same
     prefers-color-scheme it keys off. */
  @media (prefers-color-scheme: dark) {
    .p-header-logo img {
      filter: none !important;
    }
  }

  @media (prefers-color-scheme: light) {
    .p-header-logo img {
      filter: invert(1) hue-rotate(180deg) saturate(4) brightness(0.92) !important;
    }
  }

  .p-sectionLinks,
  .p-breadcrumbs,
  .p-description {
    background-color: #161d27 !important;
    color: #c4cdd6 !important;
    border-color: #21262d !important;
  }

  /* The light style's active-tab pill is a bright block here */
  .p-navEl.is-selected,
  .p-navEl.is-selected .p-navEl-link {
    background-color: #21303f !important;
    color: #ffffff !important;
  }

  /* The mobile off-canvas nav marks the current section on a different node than
     the desktop bar, so the rule above misses it. */
  .offCanvasMenu-linkHolder.is-selected {
    background-color: #21303f !important;
  }

  /* Guest / info notice banner */
  .notice,
  .notice--block,
  .notices .notice {
    background-color: #16242e !important;
    border-color: #2970a3 !important;
    color: #c4cdd6 !important;
  }

  /* A white gradient mask over the truncated preview */
  .contentRow-fader {
    background-image: linear-gradient(rgba(28, 33, 40, 0), #1c2128 80%) !important;
  }

  /* A direct `--xf-blockFooterTextColor` declaration beats the body colour our
     .block rules inherit down. `.u-dimmed` / `.menu-footer` share the token. */
  .block-footer,
  .menu-footer,
  .u-dimmed {
    color: #8b949e !important;
  }

  .block-footer,
  .menu-footer {
    background-color: #161d27 !important;
    background-image: none !important;
  }

  .u-textColor {
    color: #c4cdd6 !important;
  }

  /* Content blocks / cards */
  .block,
  .block-container,
  .block-body,
  .block-row,
  .block-minorHeader,
  .blockMessage,
  .structItem,
  .structItemContainer {
    background-color: #1c2128 !important;
    color: #c4cdd6 !important;
    border-color: #262c33 !important;
  }

  .block-row {
    background-color: transparent !important;
  }

  /* `.blockMessage` above is the BASE; the status variants set plate, ink and
     feature bar WITHOUT !important, so it erases them. Reclaim at (0,2,0) from
     the `.alert-*` palette, keeping the site's feature-bar hue. `--none` is the
     variant that asks for no plate. */
  .blockMessage.blockMessage--error {
    background-color: #2d1a1a !important;
    border-color: #7d2a2c !important;
    border-left-color: #f53d43 !important;
    color: #ff7b72 !important;
  }

  .blockMessage.blockMessage--warning,
  .blockMessage.blockMessage--important {
    background-color: #2b2412 !important;
    border-color: #6b5a12 !important;
    border-left-color: #f2930d !important;
    color: #e3c46a !important;
  }

  .blockMessage.blockMessage--success {
    background-color: #182a1a !important;
    border-color: #2a5c2d !important;
    border-left-color: #3df543 !important;
    color: #7ee787 !important;
  }

  .blockMessage.blockMessage--highlight {
    background-color: #21303f !important;
    color: #ffffff !important;
  }

  .blockMessage.blockMessage--alt {
    background-color: #21262d !important;
  }

  .blockMessage.blockMessage--none {
    background-color: transparent !important;
    border-color: transparent !important;
  }

  /* The variants colour their links by inheritance, which `a:link` (0,1,1)
     would override. */
  .blockMessage--error a,
  .blockMessage--warning a,
  .blockMessage--important a,
  .blockMessage--success a {
    color: inherit !important;
  }

  .block-header,
  .block-tabHeader,
  .structItem-cell--main .structItem-title {
    background-color: #161d27 !important;
    color: #e6edf3 !important;
  }

  /* XenForo's heading BANDS are a `linear-gradient` background-IMAGE, so
     background-color reads transparent and no colour-only override clears them.
     Same gradient on the Filters bar and every popup header and tab strip. */
  .block-filterBar,
  .menu-header,
  .menu-tabHeader {
    background-color: #161d27 !important;
    background-image: none !important;
    color: #e6edf3 !important;
    border-color: #262c33 !important;
  }

  .filterBar-filterToggle,
  .filterBar-menuTrigger.is-menuOpen,
  .filterBar-menuTrigger:hover {
    background-color: #21303f !important;
    color: #ffffff !important;
  }

  /* Remaining --xf-contentHighlightBg hover/selected states; the menu and
     autocomplete rows also re-assert the dark --xf-textColor pinned on them. */
  .menu-row--highlighted,
  .menu-row--clickable:hover,
  .autoCompleteList > li.is-selected {
    background-color: #21303f !important;
    color: #ffffff !important;
  }

  .formRow-linkList > li > a:hover,
  .actionBar-action--mq.is-selected,
  .actionBar-action--view:hover,
  .blockLinkSplitToggle:hover,
  .blockLinkSplitToggle.is-selected {
    background-color: #21303f !important;
  }

  /* Notable-members page: footers + XenForo's light-style highlight */
  .memberOverviewBlock-seeMore {
    background-color: #161d27 !important;
  }

  .blockLink:hover,
  .blockLink.is-selected {
    background-color: #21303f !important;
    color: #ffffff !important;
  }

  /* An accent, not a surface border: the blanket `*` reset would grey it */
  .blockLink.is-selected {
    border-left-color: #5fb0e6 !important;
  }

  /* XenForo's remaining `--xf-contentAltBg` chips and panels.
     `.bbCodeDemoBlock-item dd` is the BB-code help page's example column. */
  .bbCodeDemoBlock-item dd,
  .smilieText,
  .tagItem,
  .reactionScore,
  .likesBar,
  .bbMediaWrapper-fallback,
  .blockStatus,
  .filterBlock,
  .block-minorTabHeader {
    background-color: #21262d !important;
    background-image: none !important;
    border-color: #2d333b !important;
    color: #c4cdd6 !important;
  }

  .smilieText:hover,
  .tagItem:hover,
  .reactionScore:hover {
    background-color: #2d333b !important;
    color: #ffffff !important;
  }

  /* Validation error + toast must still read as errors */
  .inputValidationError {
    background-color: #2d1a1a !important;
    border-color: #7d2a2c !important;
    color: #ff7b72 !important;
  }

  .flashMessage {
    background-color: #21262d !important;
    color: #e6edf3 !important;
  }

  /* The `--blocks` drawer paints its own shell and header, unreached by the
     `--nav` drawer rules. */
  .offCanvasMenu--blocks .offCanvasMenu-content {
    background-color: #1c2128 !important;
    color: #c4cdd6 !important;
  }

  .offCanvasMenu--blocks .offCanvasMenu-header {
    background-color: #161d27 !important;
    color: #e6edf3 !important;
  }

  /* Node listing (forum index) */
  .node {
    background-color: #1c2128 !important;
    border-color: #262c33 !important;
  }

  .node-body {
    background-color: transparent !important;
  }

  .node-title a,
  .structItem-title a {
    color: #cfe2f3 !important;
  }

  .node-description,
  .node-extra,
  .node-stats,
  .structItem-minor,
  .structItem-parts {
    color: #8b949e !important;
  }

  /* Posts / messages */
  .message,
  .message-inner,
  .message--post,
  .message--article {
    background-color: #1c2128 !important;
    border-color: #262c33 !important;
  }

  .message-cell--user,
  .message-user {
    background-color: #161d27 !important;
    border-color: #21262d !important;
  }

  .message-cell--main,
  .message-main,
  .message-content {
    background-color: transparent !important;
  }

  /* Narrow viewports join the stacked user cell and post with a CSS-triangle
     pointer — three transparent sides plus one coloured, on the element and again
     on its ::after. The blanket border reset would fill all eight. */
  .message-userArrow {
    border-color: transparent transparent #2d333b !important;
  }

  .message-userArrow::after {
    border-color: transparent transparent #1c2128 !important;
  }

  .message-userContent,
  .bbWrapper {
    color: #c4cdd6 !important;
  }

  .message-name a,
  .username {
    color: #cfe2f3 !important;
  }

  /* Broad `span` / `.username` rules flatten every member group to one grey.
     Re-assert with fixed hues, not the site's `hsl(var(--xf-userTitleColor*))`:
     for a light-OS user those resolve to the light style's dark navy/green. */
  .username--staff {
    color: #79c0ff !important;
  }

  .username--style3 {
    color: #ff7b72 !important;
  }

  .username--style4 {
    color: #79c0ff !important;
  }

  .username--style24 {
    color: #3fb950 !important;
  }

  /* The broad `label` rule greys the primary variant's text, and the light
     style's plate survives for a light-OS user. */
  .label--primary {
    background-color: #21303f !important;
    color: #79c0ff !important;
  }

  /* The other prefix-label variants keep bright light-style plates; alert-palette
     tints so the prefix's meaning survives. */
  .label--royalBlue,
  .label--skyBlue,
  .label--accent {
    background-color: #21303f !important;
    color: #79c0ff !important;
  }

  .label--green,
  .label--olive {
    background-color: #182a1a !important;
    color: #7ee787 !important;
  }

  .label--red,
  .label--pink,
  .label--hotPink {
    background-color: #2d1a1a !important;
    color: #ff7b72 !important;
  }

  .label--orange,
  .label--yellow {
    background-color: #2b2412 !important;
    color: #e3c46a !important;
  }

  .label--purple,
  .label--deepPurple {
    background-color: #2a1e33 !important;
    color: #d2a8ff !important;
  }

  .label--grey,
  .label--lightGrey,
  .label--subtle,
  .label--silver {
    background-color: #21262d !important;
    color: #c4cdd6 !important;
  }

  .label--lightGreen {
    background-color: #182a1a !important;
    color: #7ee787 !important;
  }

  .label--error {
    background-color: #2d1a1a !important;
    color: #ff7b72 !important;
  }

  /* Banners are `<a>` or `<span>`, so the blanket `a:link` (0,1,1) and `span`
     (0,0,1) rules beat both the class variants' ink (set without !important) and
     a custom banner's INLINE plate + ink. Each variant takes its `.label--*`
     twin's tint at two classes, to outrank `a:link`. A custom banner keeps its
     inline plate and takes a dark ink, assuming the pale plate TPU ships. Both
     custom rules are (0,1,1): they tie `a:link` and win only by sitting later. */
  a.userBanner,
  span.userBanner {
    color: #3d2f05 !important;
    border-color: currentColor !important;
  }

  .userBanner.userBanner--staff,
  .userBanner.userBanner--primary,
  .userBanner.userBanner--accent,
  .userBanner.userBanner--blue,
  .userBanner.userBanner--royalBlue,
  .userBanner.userBanner--skyBlue {
    background-color: #16242e !important;
    border-color: #2970a3 !important;
    color: #79c0ff !important;
  }

  .userBanner.userBanner--green,
  .userBanner.userBanner--olive,
  .userBanner.userBanner--lightGreen {
    background-color: #182a1a !important;
    border-color: #2a5c2d !important;
    color: #7ee787 !important;
  }

  .userBanner.userBanner--red,
  .userBanner.userBanner--pink,
  .userBanner.userBanner--hotPink {
    background-color: #2d1a1a !important;
    border-color: #7d2a2c !important;
    color: #ff7b72 !important;
  }

  .userBanner.userBanner--orange,
  .userBanner.userBanner--yellow {
    background-color: #2b2412 !important;
    border-color: #6b5a12 !important;
    color: #e3c46a !important;
  }

  .userBanner.userBanner--purple,
  .userBanner.userBanner--deepPurple {
    background-color: #2a1e33 !important;
    border-color: #4c3a5e !important;
    color: #d2a8ff !important;
  }

  .userBanner.userBanner--gray,
  .userBanner.userBanner--silver {
    background-color: #21262d !important;
    border-color: #2d333b !important;
    color: #c4cdd6 !important;
  }

  .message-userTitle,
  .userTitle {
    color: #8b949e !important;
  }

  .message-attribution,
  .message-attribution-main,
  .message-attribution-opposite,
  .message-lastEdit,
  .message-signature {
    color: #8b949e !important;
    border-color: #21262d !important;
  }

  /* Quotes inside posts */
  blockquote,
  .bbCodeBlock--quote,
  .bbCodeBlock-title {
    background-color: #161d27 !important;
    color: #c4cdd6 !important;
    border-color: #2d333b !important;
  }

  /* An accent in both of the forum's schemes, not body ink; the shared rule
     above would sink it into the quoted text. */
  .bbCodeBlock-title {
    color: #e3a008 !important;
  }

  /* Action bar (reactions / reply) */
  .actionBar,
  .actionBar-set {
    background-color: transparent !important;
  }

  /* XenForo's accent, not a surface border */
  .reactionsBar {
    background-color: #161d27 !important;
    border-left-color: #2970a3 !important;
  }

  .reactionSummary li,
  .reactionsBar .reactionSummary li {
    background-color: transparent !important;
  }

  /* Collapsed "Low quality post by" row: the site pins its #777 ink with
     !important at (0,1,0), and its hover plate is the light-style
     highlight token. */
  .message .low-quality-post {
    color: #8b949e !important;
  }

  .message .low-quality-post:hover {
    background-color: #21303f !important;
  }

  /* Neither surface exists at load time: the voter list is a `toggleTarget`
     boxed only once the result row is clicked, and the row plate only paints
     under the pointer. The `.pollResult-bar > i` fill is the site's own. */
  .pollResult--showVoters:hover {
    background-color: #21303f !important;
  }

  .pollResult-voters {
    background-color: #161d27 !important;
    color: #c4cdd6 !important;
  }

  /* XenForo writes a photoless member's letter tile plate AND ink INLINE per
     user; our blanket `a:link` !important beats that `color`, and the generated
     palette is too wide for any single ink, so replace the chip outright. The
     three-class chain matches the site's, to outrank its `--text` rule (0,3,0
     !important). */
  .avatar.avatar--default.avatar--default--dynamic,
  .avatar.avatar--default.avatar--default--text,
  .avatar.avatar--default.avatar--default--image {
    background-color: #21262d !important;
  }

  .avatar.avatar--default.avatar--default--dynamic,
  .avatar.avatar--default.avatar--default--text {
    color: #c4cdd6 !important;
  }

  /* Retint the ring so only the green dot reads */
  .message-avatar-online {
    background-color: #161d27 !important;
  }

  /* XenForo `.pageNav` pills, missed by the news-site `.pager` rules */
  .pageNav-page,
  .pageNav-jump {
    background-color: #21262d !important;
    border-color: #2d333b !important;
  }

  .pageNav-page a,
  .pageNav-jump {
    color: #d6e2ee !important;
  }

  .pageNav-page:hover,
  .pageNav-jump:hover {
    background-color: #2d333b !important;
  }

  /* Ties `.pageNav-page:hover` above and wins on order — without the `:hover`
     half the current page loses its fill under the pointer. */
  .pageNav-page--current,
  .pageNav-page--current:hover {
    background-color: #2563a8 !important;
    border-color: #2f74c0 !important;
  }

  .pageNav-page--current,
  .pageNav-page--current a {
    color: #ffffff !important;
  }

  /* Narrow viewports swap `.pageNav` for `.pageNavSimple`; Next/Last carry a
     gradient background-IMAGE, so bg-color reads transparent. */
  .pageNavSimple-el {
    background-color: #21262d !important;
    background-image: none !important;
    color: #d6e2ee !important;
    border-color: #2d333b !important;
  }

  .pageNavSimple-el--current {
    background-color: #2563a8 !important;
    color: #ffffff !important;
    border-color: #2f74c0 !important;
  }

  /* Thread-list mini page-jump pills */
  .structItem-pageJump a {
    background-color: #21262d !important;
    color: #d6e2ee !important;
    border-color: #2d333b !important;
  }

  .structItem-pageJump a:hover {
    background-color: #2d333b !important;
    color: #ffffff !important;
  }

  .actionBar-action {
    color: #8b949e !important;
  }

  .actionBar-action:hover {
    color: #9bd4ff !important;
  }

  /* Tabs / data lists */
  .tabs,
  .tabs-tab,
  .dataList,
  .dataList-row,
  .dataList-cell {
    background-color: transparent !important;
    color: #c4cdd6 !important;
    border-color: #21262d !important;
  }

  .tabs-tab.is-active {
    color: #9bd4ff !important;
    border-color: #5fb0e6 !important;
  }

  /* Reply editor / rich text area */
  .fr-box .fr-wrapper,
  .fr-toolbar,
  .fr-element,
  .input--textarea {
    background-color: #0d1117 !important;
    color: #e6edf3 !important;
    border-color: #2d333b !important;
  }

  /* The Log in / Register modal, absent from the DOM until clicked */
  .overlay {
    background-color: #1c2128 !important;
    border-color: #2d333b !important;
  }

  .overlay-content,
  .overlay .blocks-textJoiner,
  .overlay .blocks-textJoiner em {
    color: #c4cdd6 !important;
  }

  .overlay-title {
    background-color: #161d27 !important;
    background-image: none !important;
    color: #e6edf3 !important;
    border-color: #262c33 !important;
  }

  /* The left LABEL column is a light plate, not a text colour */
  .formRow > dt,
  .formRow-label {
    background-color: #161d27 !important;
    color: #c4cdd6 !important;
  }

  /* An ABSOLUTELY POSITIONED sibling, not an ancestor of anything */
  .formSubmitRow-bar {
    background-color: #161d27 !important;
  }

  /* Welded to an input: password "Show", share copy-link */
  .inputGroup-text,
  .shareInput-button {
    background-color: #21262d !important;
    color: #5fb0e6 !important;
    border-color: #2d333b !important;
  }

  /* Tooltip and profile header share `.memberProfileBanner`, and the tooltip's
     lines keep the light style's near-black ink. An uploaded banner is a
     background-IMAGE on this class and paints over the colour. */
  .memberTooltip-header,
  .memberProfileBanner {
    background-color: #161d27 !important;
  }

  /* Only one member of the --xf-contentAltBg family */
  .message-responseRow {
    background-color: #161d27 !important;
  }

  .tooltip-content,
  .tooltip-content-inner,
  .memberTooltip,
  .memberTooltip-headerInfo,
  .memberTooltip-blurbContainer,
  .memberTooltip-blurb {
    color: #c4cdd6 !important;
  }

  /* An image attachment covers the plate; a non-image file, a broken image and
     every lazy-load frame show it. */
  .attachmentList .file,
  .attachmentList .file--linked,
  .file-preview {
    background-color: #161d27 !important;
    border-color: #262c33 !important;
  }

  /* A white gradient wash over truncated text; retint per surface */
  .bbCodeBlock-expandLink {
    background-image: linear-gradient(rgba(13, 17, 23, 0), #0d1117 80%) !important;
  }

  .bbCodeBlock--quote .bbCodeBlock-expandLink {
    background-image: linear-gradient(rgba(22, 29, 39, 0), #161d27 80%) !important;
  }

  /* ---- Semantic / status colors ---- */

  .green,
  .label--green,
  .badge--green,
  span[style*="color: green"],
  .text-success {
    color: #3fb950 !important;
  }

  .red,
  .label--red,
  .badge--red,
  span[style*="color: red"],
  .text-error {
    color: #ff7b72 !important;
  }

  .orange,
  .label--orange,
  span[style*="color: orange"] {
    color: #e3a008 !important;
  }

  /* Keep the hue, invert the value. `color: inherit` is needed because the broad
     `p, li, span` body rule would wash the ink to grey. */
  .alert-success {
    background-color: #182a1a !important;
    border-color: #2a5c2d !important;
    color: #7ee787 !important;
  }

  .alert-info {
    background-color: #16242e !important;
    border-color: #2970a3 !important;
    color: #79c0ff !important;
  }

  .alert-warning {
    background-color: #2b2412 !important;
    border-color: #6b5a12 !important;
    color: #e3c46a !important;
  }

  .alert-danger {
    background-color: #2d1a1a !important;
    border-color: #7d2a2c !important;
    color: #ff7b72 !important;
  }

  .alert p,
  .alert li,
  .alert span,
  .alert h4 {
    color: inherit !important;
  }

  /* Remaining light cards on low-traffic pages */
  .awards .award,
  .media-asset,
  .trivia .messagecontainer {
    background-color: #1c2128 !important;
    border-color: #262c33 !important;
  }

  .staff-member:nth-child(odd) {
    background-color: #1c2128 !important;
  }

  /* ---- Firewall / bot-check interstitial ----
     A proof-of-work firewall fronts the WHOLE domain, replacing the page with a
     standalone `main.card` document, its own palette keyed off
     prefers-color-scheme — under a light OS it stays white under our light ink.
     `main.card` exists nowhere else. Overriding its tokens also reaches the
     progress track and drag-captcha rail, painted with an INLINE `background:
     var(--progress-bg)` no selector of ours can outrank. `--progress-fill` stays
     green: it is the signal. */
  main.card {
    --bg: #14181d;
    --card: #1c2128;
    --text: #e6edf3;
    --muted: #8b949e;
    --border: #262c33;
    --progress-bg: #30363d;
    --btn-bg: #2f74c0;
    background-color: #1c2128 !important;
    border-color: #262c33 !important;
    box-shadow: 0 8px 24px rgba(0, 0, 0, 0.5) !important;
  }

  main.card h1,
  main.card p,
  main.card dt,
  main.card dd {
    color: #e6edf3 !important;
  }

  /* Muted text ON the card, no plate */
  main.card footer,
  main.card dl.meta,
  main.card .muted {
    background-color: transparent !important;
    border-top: 0 !important;
    color: #8b949e !important;
  }

  main.card footer a {
    color: #5fb0e6 !important;
  }

  /* Selection */
  ::selection {
    background-color: #2f74c0 !important;
    color: #ffffff !important;
  }

  /* Horizontal rules / dividers */
  hr {
    border-color: #262c33 !important;
    background-color: #262c33 !important;
  }

  /* Scrollbar */
  * {
    scrollbar-color: #2d333b #14181d;
  }
}
